import subprocess, os
def run(args, env=None, cwd=None, inp=None):
    e=dict(os.environ)
    if env: 
        for k,v in env.items():
            if v is None: e.pop(k,None)
            else: e[k]=v
    r=subprocess.run(["/workspace/executable"]+args, capture_output=True, text=True, env=e, cwd=cwd, input=inp)
    print(f"$ direnv {args} exit={r.returncode}")
    if r.stdout: print("OUT:", repr(r.stdout))
    if r.stderr: print("ERR:", repr(r.stderr))
    print()
    return r

for typ in ["status","-status","--status","---status","STATUS","error","-error","--error","Error","--STATUS","--error=x"]:
