import subprocess, os, pathlib, shutil, json, base64, zlib, gzip, hashlib
# take a DIRENV_DIFF and WATCHES from previous run ? rerun fresh export json
EXE="/workspace/executable"
ROOT="/tmp/projtest"
home=pathlib.Path(ROOT)/"home"; proj=pathlib.Path(ROOT)/"proj"
def env(extra=None):
    e={"HOME":str(home),"PATH":os.environ["PATH"]}
    if extra: e.update(extra)
    return e
r=subprocess.run([EXE,"export","json"],capture_output=True,text=True,env=env(),cwd=proj)
j=json.loads(r.stdout)
for k,v in j.items():
    print(k,v)
print()
for name in ["DIRENV_DIFF","DIRENV_WATCHES"]:
    s=j[name]
    print(name, len(s), s)
    # try base64 decodings
    for altchars, label in [(None,"std"), (b"-_","urlsafe")]:
        try:
            if altchars: b=base64.b64decode(s, altchars=altchars, validate=False)
            else: b=base64.b64decode(s)
            print(" ",label, b[:20], len(b))
            try: print("   zlib:", zlib.decompress(b))
            except Exception as e: print("   zlib fail",e)
            try: print("   gzip:", gzip.decompress(b))
            except Exception as e: print("   gzip fail",e)
        except Exception as e:
            print(" ",label, "b64 fail", e)
