    # brute: translate '-_' to '+/' and std decode is same as urlsafe.
    print()

# hashes
envrc=(proj/".envrc").read_bytes()
print("envrc bytes", envrc)
candidates={
 "sha256(content)": hashlib.sha256(envrc).hexdigest(),
 "sha256(path)": hashlib.sha256(str(proj/".envrc").encode()).hexdigest(),
 "sha256(path+content)": hashlib.sha256(str(proj/".envrc").encode()+envrc).hexdigest(),
 "sha256(content+path)": hashlib.sha256(envrc+str(proj/".envrc").encode()).hexdigest(),
 "sha256(dir)": hashlib.sha256(str(proj).encode()).hexdigest(),
}
for k,v in candidates.items(): print(k,v)
print("allow hash observed fd7e7d0c8fc05522d3b89572e6feeee75d830d3f877e9aaba9bf73c2a04daf90")
print("deny hash observed a7c86544e63b44ecdb67a717557b47f00d4cb250dbfce700b33470fe1e26d739")

# dump command
r=subprocess.run([EXE,"dump"],capture_output=True,text=True,env=env({"FOO":"bar","CUSTOM_X":"y z"}),cwd=proj)
print("dump no args", r.returncode, repr(r.stdout), repr(r.stderr))
# dump json?
