    r=subprocess.run([EXE]+args,capture_output=True,text=True,env=env({"FOO":"bar"}),cwd=proj)
    print(args, r.returncode, repr(r.stdout[:1000]), repr(r.stderr[:500]))

# show_dump
# first get dump output
