            self.send_response(200); self.send_header("Content-Length","0"); self.end_headers(); return
        if self.path.startswith("/echo"):
            body=(self.path+"|"+self.headers.get("User-Agent","")).encode(); self.send_response(200); self.send_header("Content-Length",str(len(body))); self.end_headers(); self.wfile.write(body); return
