{"command":"cat > go.mod <<'EOF'
module reimplementation

go 1.21

require github.com/BurntSushi/toml v1.6.0
EOF
cat > main.go <<'EOF'
package main

import (
	"fmt"
	"os"
)

const version = "2.37.1"

var selfPath string

func main() {
	// os.Executable mirrors the reference behaviour on Linux: it resolves
	// /proc/self/exe and therefore symlinks to the real file.
	if p, err := os.Executable(); err == nil {
		selfPath = p
	} else {
		selfPath = os.Args[0]
	}
	// Debug logging is enabled early, based solely on the environment.
	initDebug()
	args := make([]string, len(os.Args))
	copy(args, os.Args)
	if len(args) > 1 {
		switch args[1] {
		case "--help":
			args[1] = "help"
		case "--version":
			args[1] = "version"
		}
	}
	code := dispatch(args)
	if code != 0 {
		os.Exit(code)
	}
}

// fail prints an error in the fixed top-level format.  It deliberately does
// not go through the configurable log format: even after a config file has
// been loaded the reference keeps this red "direnv: error ..." form.
func fail(err error) int {
	if err != nil {
		fmt.Fprintf(os.Stderr, "\x1b[31mdirenv: error %s\x1b[0m\n", err.Error())
		return 1
	}
	return 0
}
EOF
cat > log.go <<'EOF'
package main

import (
	"fmt"
	"log"
	"os"
	"regexp"
	"strconv"
	"strings"
	"time"
)

// Configurable status/error log formats.
//
// Before a configuration file is parsed the reference exports two distinct
// formats (a reset-prefixed status format and a red error format).  Once a
// TOML configuration file has been parsed successfully, setupLogging resets
// both to a plain base and the status format may be overridden by the
// configuration and then by the $DIRENV_LOG_FORMAT environment variable.
var (
	statusLogFormat = "\x1b[0mdirenv: %s"
	errorLogFormat  = "\x1b[31mdirenv: %s\x1b[0m"
	logRegexp       *regexp.Regexp
	// The reference's status/error printing goes through a stdlib log.Logger
	// with no flags/prefix.  Replicating that (including the way Printf is
	// called with a pre-formatted string) reproduces a number of observable
	// %-formatting quirks.
	plainLogger = log.New(os.Stderr, "", 0)
)

func logStatus(format string, args ...interface{}) {
	if statusLogFormat == "" {
		return
	}
	if logRegexp != nil {
		msg := fmt.Sprintf(format, args...)
		if !logRegexp.MatchString(msg) {
			return
		}
	}
	plainLogger.Printf(fmt.Sprintf(statusLogFormat+"\n", format), args...)
}

func logError(format string, args ...interface{}) {
	if errorLogFormat == "" {
		return
	}
	plainLogger.Printf(fmt.Sprintf(errorLogFormat+"\n", format), args...)
}

func setupLogging(g tomlGlobal) error {
	statusLogFormat = "direnv: %s"
	errorLogFormat = "direnv: %s"
	if g.LogFormat == "-" {
		statusLogFormat = ""
	} else if g.LogFormat != "" {
		statusLogFormat = g.LogFormat
	}
	if v, ok := os.LookupEnv("DIRENV_LOG_FORMAT"); ok {
		statusLogFormat = v
	}
	if g.LogFilter != "" {
		re, err := regexp.Compile(g.LogFilter)
		if err != nil {
			return fmt.Errorf("error in log filter: %w", err)
		}
		logRegexp = re
	}
	return nil
}

// --- debug logging ---------------------------------------------------------

var debugEnabled bool

func initDebug() {
	v, ok := os.LookupEnv("DIRENV_DEBUG")
	if !ok {
		return
	}
	if b, err := strconv.ParseBool(v); err == nil && b {
		debugEnabled = true
	}
}

// debugLogf intentionally takes an explicit file/line: the reference emits
// its internal source locations when DIRENV_DEBUG is enabled.  We reproduce
// the common observed lines literally rather than our own call sites.
func debugLogf(ctx, loc, format string, args ...interface{}) {
	if !debugEnabled {
		return
	}
	msg := fmt.Sprintf(format, args...)
	t := time.Now().Format("15:04:05")
	if ctx == "" {
		fmt.Fprintf(os.Stderr, "direnv: %s %s: %s\n", t, loc, msg)
	} else {
		fmt.Fprintf(os.Stderr, "direnv: %s:%s %s: %s\n", ctx, t, loc, msg)
	}
}

// debugContext is a tiny helper mirroring the reference's nested log context
// ("export", "export:update", "cmd_edit", ...).  Empty segments are kept.
type debugContext struct{ name string }

func newDebugContext(name string) debugContext { return debugContext{name: name} }
func (d debugContext) sub(name string) debugContext {
	if d.name == "" {
		return debugContext{name: name}
	}
	return debugContext{name: d.name + ":" + name}
}
func (d debugContext) logf(loc, format string, args ...interface{}) {
	debugLogf(d.name, loc, format, args...)
}

var logCtx debugContext

func init() {
	// Prevent the standard logger (used only for reimplementing logStatus /
	// logError above) from adding any decorations.
	plainLogger.SetFlags(0)
	plainLogger.SetPrefix("")
	_ = strings.TrimSpace
