cat > env.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"sort"
	"strings"
)

type Env map[string]string

func newEnv() Env {
	env := make(Env)
	for _, kv := range os.Environ() {
		if k, v, ok := strings.Cut(kv, "="); ok {
			env[k] = v
		}
	}
	return env
}

// envFromSlice is used where an environment is supplied explicitly (tests in
// the reference are not relevant here; the process environment is the only
// source in normal operation).
func envFromSlice(list []string) Env {
	env := make(Env, len(list))
	for _, kv := range list {
		if k, v, ok := strings.Cut(kv, "="); ok {
			env[k] = v
		}
	}
	return env
}

func (e Env) copy() Env {
	out := make(Env, len(e))
	for k, v := range e {
		out[k] = v
	}
	return out
}

func (e Env) toSlice() []string {
	out := make([]string, 0, len(e))
	for k, v := range e {
		out = append(out, k+"="+v)
	}
	return out
}

// Keys that are excluded when computing an environment difference between the
// environment before an .envrc is evaluated and the environment that the
// bash sub-process dumps afterwards.  Determined behaviourally: assignments
// to (or unsets of) any of these inside an .envrc never surface in the
// DIRENV_DIFF or in shell export output generated from a load.
var ignoredDiffKeys = map[string]bool{
	"_":                true,
	"COMP_WORDBREAKS":  true,
	"DIRENV_BASH":      true,
	"DIRENV_CONFIG":    true,
	"DIRENV_IN_ENVRC":  true,
	"OLDPWD":           true,
	"PS1":              true,
	"PWD":              true,
	"SHELL":            true,
	"SHLVL":            true,
}

type envDiff struct {
	Prev Env `json:"p"`
	Next Env `json:"n"`
}

func newEnvDiff() *envDiff {
	return &envDiff{Prev: make(Env), Next: make(Env)}
}

func buildEnvDiff(prev, next Env) *envDiff {
	d := newEnvDiff()
	keys := make(map[string]bool)
	for k := range prev {
		keys[k] = true
	}
	for k := range next {
		keys[k] = true
	}
	for k := range keys {
		if ignoredDiffKeys[k] {
			continue
		}
		pv, pok := prev[k]
		nv, nok := next[k]
		if pok == nok && pv == nv {
			continue
		}
		if pok {
			d.Prev[k] = pv
		}
		if nok {
			d.Next[k] = nv
		}
	}
	return d
}

func (d *envDiff) serialize() string {
	if d.Prev == nil {
		d.Prev = make(Env)
	}
	if d.Next == nil {
		d.Next = make(Env)
	}
	return gzMarshal(d)
}

// applyTo applies the forward direction of this diff to e (in place logic on
// a copy): keys in Next are set, keys only in Prev are removed.
func (d *envDiff) applyTo(e Env) Env {
	out := e.copy()
	for k := range d.Prev {
		if _, ok := d.Next[k]; !ok {
			delete(out, k)
		}
	}
	for k, v := range d.Next {
		out[k] = v
	}
	return out
}

// summary renders the "export +A -B ~C" line.  Variables whose name begins
// with DIRENV_ are always omitted, as are ignored keys (already absent).
func (d *envDiff) summary() string {
	var added, removed, changed []string
	keyset := make(map[string]bool)
	for k := range d.Prev {
		keyset[k] = true
	}
	for k := range d.Next {
		keyset[k] = true
	}
	for k := range keyset {
		if strings.HasPrefix(k, "DIRENV_") {
			continue
		}
		_, pok := d.Prev[k]
		_, nok := d.Next[k]
		switch {
		case pok && nok:
			changed = append(changed, k)
		case nok:
			added = append(added, k)
		case pok:
			removed = append(removed, k)
		}
	}
	sort.Strings(added)
	sort.Strings(removed)
	sort.Strings(changed)
	var parts []string
	for _, k := range added {
		parts = append(parts, "+"+k)
	}
	for _, k := range removed {
		parts = append(parts, "-"+k)
	}
	for _, k := range changed {
		parts = append(parts, "~"+k)
	}
	return strings.Join(parts, " ")
}

// revert returns the environment as it was before the diff recorded in
// DIRENV_DIFF was applied.  The four core direnv state variables are removed
// first (so a no-diff unload still cleans them up); values recorded in Prev
// are then restored over the deletions.
func (e Env) revert() (Env, error) {
	s, present := e["DIRENV_DIFF"]
	out := e.copy()
	var d *envDiff
	if present && s != "" {
		d = newEnvDiff()
		if err := gzUnmarshal(s, d); err != nil {
			return nil, fmt.Errorf("Revert() failed: %w", err)
		}
	} else {
		d = newEnvDiff()
	}
	for _, k := range []string{"DIRENV_DIFF", "DIRENV_DIR", "DIRENV_FILE", "DIRENV_WATCHES"} {
		delete(out, k)
	}
	for k := range d.Next {
		delete(out, k)
	}
	for k, v := range d.Prev {
		out[k] = v
	}
	return out, nil
}
EOF
