package main

import (
	"fmt"
	"os"
	"sort"
	"strings"
)

type Env map[string]string

func newEnv() Env {
	env := make(Env)
	for _, kv := range os.Environ() {
		if k, v, ok := strings.Cut(kv, "="); ok {
			env[k] = v
		}
	}
	return env
}

// envFromSlice is used where an environment is supplied explicitly (tests in
// the reference are not relevant here; the process environment is the only
// source in normal operation).
func envFromSlice(list []string) Env {
	env := make(Env, len(list))
	for _, kv := range list {
		if k, v, ok := strings.Cut(kv, "="); ok {
			env[k] = v
		}
	}
	return env
}

func (e Env) copy() Env {
	out := make(Env, len(e))
	for k, v := range e {
		out[k] = v
	}
	return out
}

func (e Env) toSlice() []string {
	out := make([]string, 0, len(e))
	for k, v := range e {
		out = append(out, k+"="+v)
	}
	return out
}

