// environment before an .envrc is evaluated and the environment that the
// bash sub-process dumps afterwards.  Determined behaviourally: assignments
// to (or unsets of) any of these inside an .envrc never surface in the
// DIRENV_DIFF or in shell export output generated from a load.
var ignoredDiffKeys = map[string]bool{
	"_":                true,
	"COMP_WORDBREAKS":  true,
	"DIRENV_BASH":      true,
	"DIRENV_CONFIG":    true,
	"DIRENV_IN_ENVRC":  true,
	"OLDPWD":           true,
	"PS1":              true,
	"PWD":              true,
	"SHELL":            true,
	"SHLVL":            true,
}

type envDiff struct {
	Prev Env `json:"p"`
	Next Env `json:"n"`
}

func newEnvDiff() *envDiff {
	return &envDiff{Prev: make(Env), Next: make(Env)}
}

func buildEnvDiff(prev, next Env) *envDiff {
	d := newEnvDiff()
	keys := make(map[string]bool)
	for k := range prev {
		keys[k] = true
	}
	for k := range next {
		keys[k] = true
	}
	for k := range keys {
		if ignoredDiffKeys[k] {
			continue
		}
		pv, pok := prev[k]
		nv, nok := next[k]
		if pok == nok && pv == nv {
			continue
		}
		if pok {
			d.Prev[k] = pv
		}
		if nok {
			d.Next[k] = nv
		}
	}
	return d
