package main

import (
	"fmt"
	"os"
	"path/filepath"
)

type fileTime struct {
	Path    string `json:"path"`
	Modtime int64  `json:"modtime"`
	Exists  bool   `json:"exists"`
}

// getLatestStat returns the newest mtime (in whole unix seconds) of the
// Lstat and Stat results for path.  Errors from Lstat are returned as-is;
// errors from Stat are also returned as-is (so a broken symlink is reported
// as not existing by callers that check os.IsNotExist).
func getLatestStat(path string) (int64, error) {
	lfi, err := os.Lstat(path)
	if err != nil {
		debugLogf("", "file_times.go:174", "getLatestStat,Lstat: %s: error: %v", path, err)
		return 0, err
	}
	lmtime := lfi.ModTime().Unix()
	fi, err := os.Stat(path)
	if err != nil {
		debugLogf("", "file_times.go:181", "getLatestStat,Stat: %s: error: %v (Lstat time: %d)", path, err, lmtime)
		return 0, err
	}
	mtime := fi.ModTime().Unix()
	if lmtime > mtime {
		debugLogf("", "file_times.go:188", "getLatestStat: %s: Lstat: %d, Stat: %d -> preferring Lstat", path, lmtime, mtime)
		return lmtime, nil
	}
	debugLogf("", "file_times.go:192", "getLatestStat: %s: Lstat: %d, Stat: %d -> preferring Stat", path, lmtime, mtime)
	return mtime, nil
}

// update refreshes ft from the filesystem.  It is used both when a fresh
// record is created (path already absolute) and by [*fileTime.check] via
// getLatestStat directly.
func (ft *fileTime) update() error {
	mtime, err := getLatestStat(ft.Path)
	if err != nil {
		if os.IsNotExist(err) {
			ft.Modtime = 0
			ft.Exists = false
			return nil
		}
		return err
	}
	ft.Modtime = mtime
	ft.Exists = true
	return nil
}

func newFileTime(path string) (*fileTime, error) {
	abs, err := filepath.Abs(path)
	if err == nil {
		path = abs
	}
	// NB: stat using the path as given is important for the wording of
	// errors (e.g. `lstat file.txt/bogus: not a directory` uses the raw
	// argument).  getLatestStat is therefore called through updateStat on
	// the caller side; here the caller passes a path whose stat error has
	// already been produced with the right spelling.  To keep the same
	// behaviour, callers use newFileTimeFrom directly.
	ft := &fileTime{Path: path}
	if err := ft.update(); err != nil {
		return nil, err
	}
	return ft, nil
}

// newFileTimeFrom stats rawPath (for error messages) but stores storedPath.
func fileTimeFor(rawPath, storedPath string) (*fileTime, error) {
	mtime, err := getLatestStat(rawPath)
	if err != nil {
		if os.IsNotExist(err) {
			return &fileTime{Path: storedPath, Modtime: 0, Exists: false}, nil
		}
		return nil, err
	}
	return &fileTime{Path: storedPath, Modtime: mtime, Exists: true}, nil
}

func absPath(p string) string {
	if abs, err := filepath.Abs(p); err == nil {
		return abs
	}
	return p
}

// check reports whether the recorded state still matches the filesystem.
func (ft *fileTime) check() error {
	mtime, err := getLatestStat(ft.Path)
	if err != nil {
		if os.IsNotExist(err) {
			if !ft.Exists {
				debugLogf("", "file_times.go:140", "Check: %s: up to date", ft.Path)
				return nil
			}
			debugLogf("", "file_times.go:126", "Stat Check: %s: gone", ft.Path)
			return fmt.Errorf("File %q is missing (Stat)", ft.Path)
		}
		debugLogf("", "file_times.go:130", "Stat Check: %s: ERR: %v", ft.Path, err)
		return err
	}
	if !ft.Exists {
		debugLogf("", "file_times.go:133", "Check: %s: appeared", ft.Path)
		return fmt.Errorf("File %q newly created", ft.Path)
	}
