	// errors (e.g. `lstat file.txt/bogus: not a directory` uses the raw
	// argument).  getLatestStat is therefore called through updateStat on
	// the caller side; here the caller passes a path whose stat error has
	// already been produced with the right spelling.  To keep the same
	// behaviour, callers use newFileTimeFrom directly.
	ft := &fileTime{Path: path}
	if err := ft.update(); err != nil {
		return nil, err
	}
	return ft, nil
}

// newFileTimeFrom stats rawPath (for error messages) but stores storedPath.
func fileTimeFor(rawPath, storedPath string) (*fileTime, error) {
	mtime, err := getLatestStat(rawPath)
	if err != nil {
		if os.IsNotExist(err) {
			return &fileTime{Path: storedPath, Modtime: 0, Exists: false}, nil
		}
		return nil, err
	}
	return &fileTime{Path: storedPath, Modtime: mtime, Exists: true}, nil
}

func absPath(p string) string {
	if abs, err := filepath.Abs(p); err == nil {
		return abs
	}
	return p
}

// check reports whether the recorded state still matches the filesystem.
func (ft *fileTime) check() error {
	mtime, err := getLatestStat(ft.Path)
	if err != nil {
		if os.IsNotExist(err) {
			if !ft.Exists {
				debugLogf("", "file_times.go:140", "Check: %s: up to date", ft.Path)
				return nil
			}
			debugLogf("", "file_times.go:126", "Stat Check: %s: gone", ft.Path)
			return fmt.Errorf("File %q is missing (Stat)", ft.Path)
		}
		debugLogf("", "file_times.go:130", "Stat Check: %s: ERR: %v", ft.Path, err)
		return err
	}
	if !ft.Exists {
		debugLogf("", "file_times.go:133", "Check: %s: appeared", ft.Path)
		return fmt.Errorf("File %q newly created", ft.Path)
	}
	if mtime != ft.Modtime {
		debugLogf("", "file_times.go:136", "Check: %s: stale (stat: %d, lastcheck: %d)", ft.Path, mtime, ft.Modtime)
		return fmt.Errorf("File %q has changed", ft.Path)
	}
	debugLogf("", "file_times.go:140", "Check: %s: up to date", ft.Path)
	return nil
}

// --- a list of file times ---------------------------------------------------

type fileTimes struct {
	list []fileTime
}

func newFileTimes() *fileTimes { return &fileTimes{list: []fileTime{}} }

// add records rawPath.  storedPath is the absolute form; the stat (and hence
// any error message) uses rawPath exactly as supplied.
func (fts *fileTimes) add(rawPath string) error {
	stored := absPath(rawPath)
	// Stat with the raw spelling first so errors read correctly.
	mtime, err := getLatestStat(rawPath)
	var rec fileTime
	if err != nil {
		if os.IsNotExist(err) {
			rec = fileTime{Path: stored, Modtime: 0, Exists: false}
		} else {
			return err
		}
	} else {
		rec = fileTime{Path: stored, Modtime: mtime, Exists: true}
	}
	for i := range fts.list {
		if fts.list[i].Path == stored {
			fts.list[i] = rec
			return nil
		}
	}
	fts.list = append(fts.list, rec)
	return nil
}

// addWithTime is used by watch-list: existence is always recorded as true.
func (fts *fileTimes) addWithTime(path string, modtime int64) {
	stored := absPath(path)
	rec := fileTime{Path: stored, Modtime: modtime, Exists: true}
	for i := range fts.list {
		if fts.list[i].Path == stored {
			fts.list[i] = rec
			return
		}
	}
	fts.list = append(fts.list, rec)
}

func (fts *fileTimes) find(path string) *fileTime {
	for i := range fts.list {
		if fts.list[i].Path == path {
			return &fts.list[i]
		}
	}
	return nil
}

// checkAll returns the first stale check error, if any.  An empty list is
// treated as stale - observed behaviour when DIRENV_WATCHES decodes to [].
func (fts *fileTimes) checkAll() error {
	if len(fts.list) == 0 {
		return fmt.Errorf("no watches")
	}
	for i := range fts.list {
		if err := fts.list[i].check(); err != nil {
			return err
		}
	}
	return nil
}

func (fts *fileTimes) marshal() string {
	list := fts.list
	if list == nil {
		list = []fileTime{}
	}
	return gzMarshal(list)
}

// getWatches reads DIRENV_WATCHES from env.  Absence of the variable yields
// an empty list; presence (even empty) is decoded and may error.
func getWatches(env Env) (*fileTimes, error) {
	s, ok := env["DIRENV_WATCHES"]
	if !ok {
		return newFileTimes(), nil
	}
	fts := newFileTimes()
	var list []fileTime
	if err := gzUnmarshal(s, &list); err != nil {
		return nil, err
	}
	if list != nil {
		fts.list = list
	}
	return fts, nil
}
EOF
gofmt -w file_times.go"}

