	if keyPresent(md, "disable_stdin") {
		cfg.DisableStdin = g.DisableStdin
	}
	if keyPresent(md, "hide_env_diff") {
		cfg.HideEnvDiff = g.HideEnvDiff
	}
	if keyPresent(md, "load_dotenv") {
		cfg.LoadDotenv = g.LoadDotenv
	}
	if keyPresent(md, "strict_env") {
		cfg.StrictEnv = g.StrictEnv
	}
	if keyPresent(md, "warn_timeout") {
		cfg.WarnTimeout = g.WarnTimeout.Duration
	}
}

func applyGlobalSection(cfg *config, g tomlGlobal, md toml.MetaData) {
	if keyPresent(md, "global", "bash_path") {
		cfg.BashPath = g.BashPath
	}
	if keyPresent(md, "global", "disable_stdin") {
		cfg.DisableStdin = g.DisableStdin
	}
	if keyPresent(md, "global", "hide_env_diff") {
		cfg.HideEnvDiff = g.HideEnvDiff
	}
	if keyPresent(md, "global", "load_dotenv") {
		cfg.LoadDotenv = g.LoadDotenv
	}
	if keyPresent(md, "global", "strict_env") {
		cfg.StrictEnv = g.StrictEnv
	}
	if keyPresent(md, "global", "warn_timeout") {
		cfg.WarnTimeout = g.WarnTimeout.Duration
	}
}

// --- RC finding ------------------------------------------------------------

func (c *config) findRC() *rc { return findRCFrom(c.workDir, c) }

func findRCFrom(wd string, cfg *config) *rc {
	if wd == "" {
		return nil
	}
	dir := wd
	for {
		candidates := []string{filepath.Join(dir, ".envrc")}
		if cfg.LoadDotenv {
			candidates = append(candidates, filepath.Join(dir, ".env"))
		}
		for _, cand := range candidates {
			if r, err := newRC(cand, cfg); err == nil {
				return r
			}
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return nil
		}
		dir = parent
	}
}

func (c *config) loadedRC() *rc {
	rcFile := c.env["DIRENV_FILE"]
	if rcFile == "" {
		debugLogf("", "config.go:258", "RCFile is blank - loadedRC is nil")
		return nil
	}
	r, err := newRC(rcFile, c)
	if err != nil {
		return nil
	}
	// The watches recorded in the environment replace the freshly computed
	// ones; an undecodable/missing value means there is no loaded RC.
	s, ok := c.env["DIRENV_WATCHES"]
	if !ok {
		return nil
	}
	var list []fileTime
	if err := gzUnmarshal(s, &list); err != nil {
		return nil
	}
	if list == nil {
		list = []fileTime{}
	}
	r.times = &fileTimes{list: list}
	return r
}

// findRCForAllow resolves the optional PATH_TO_RC argument used by
// allow/block.  It returns the found RC (searching upwards from clr the
// argument or the working directory) plus any stat error for an explicit
// argument that does not exist.
func (c *config) findRCForAllow(arg string, hasArg bool) (*rc, error) {
	searchDir := c.workDir
	if hasArg {
		absArg := absPath(arg)
		fi, err := os.Lstat(absArg)
		if err != nil {
			return nil, err
		}
		if fi.IsDir() {
			searchDir = absArg
		} else {
			searchDir = filepath.Dir(absArg)
		}
	}
	r := findRCFrom(searchDir, c)
	if r == nil {
		return nil, fmt.Errorf(".envrc file not found")
	}
	return r, nil
}
