package main

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

type allowStatus int

const (
	allowedStatus allowStatus = 0
	blockedStatus allowStatus = 1
	deniedStatus  allowStatus = 2
)

type rc struct {
	path      string
	allowPath string
	denyPath  string
	times     *fileTimes
	cfg       *config
}

func hashString(s string) string {
	h := sha256.Sum256([]byte(s))
	return hex.EncodeToString(h[:])
}

// hashForPath is sha256("<abs path>\n" + file content), matching the names of
// files in the allow directory.  With empty content it also yields the deny
// and allowed-required parent hash (both are sha256("<path>\n")).
func hashForPath(absPath string, content []byte) string {
	h := sha256.New()
	h.Write([]byte(absPath))
	h.Write([]byte("\n"))
	h.Write(content)
	return hex.EncodeToString(h.Sum(nil))
}

func newRC(path string, cfg *config) (*rc, error) {
	content, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	abs := absPath(path)
	allowPath := filepath.Join(cfg.allowDir(), hashForPath(abs, content))
	denyPath := filepath.Join(cfg.denyDir(), hashForPath(abs, nil))
	r := &rc{path: path, allowPath: allowPath, denyPath: denyPath, cfg: cfg, times: newFileTimes()}
	// The initial watches are recorded using the spelling of each path as
	// the reference does (absolute paths everywhere except that the RC's
	// own path retains the spelling it was constructed with - which is
	// absolute for found RCs and the env value for loaded RCs).
	for _, p := range []string{path, allowPath, denyPath} {
		rec, err := fileTimeFor(p, absPath(p))
		if err != nil {
			return nil, err
		}
		r.times.list = append(r.times.list, *rec)
	}
	return r, nil
}

func (r *rc) allowed() allowStatus {
	abs := absPath(r.path)
	for _, prefix := range r.cfg.whitelistPrefix {
		if strings.HasPrefix(abs, prefix) {
			return allowedStatus
		}
	}
	if r.cfg.whitelistExact[abs] {
		return allowedStatus
	}
	if _, err := os.Stat(r.denyPath); err == nil {
		return deniedStatus
	}
	if _, err := os.Stat(r.allowPath); err == nil {
		return allowedStatus
	}
	return blockedStatus
}

func (r *rc) allow() error {
	if err := os.MkdirAll(filepath.Dir(r.allowPath), 0o755); err != nil {
		return err
	}
	abs := absPath(r.path)
	if err := os.WriteFile(r.allowPath, []byte(abs+"\n"), 0o644); err != nil {
		return err
	}
	_ = os.Remove(r.denyPath)
	return nil
}

func (r *rc) deny() error {
	if err := os.MkdirAll(filepath.Dir(r.denyPath), 0o755); err != nil {
		return err
	}
	abs := absPath(r.path)
	if err := os.WriteFile(r.denyPath, []byte(abs+"\n"), 0o644); err != nil {
		return err
	}
	_ = os.Remove(r.allowPath)
	return nil
}

func (r *rc) touch() error {
	now := currentTime()
	return os.Chtimes(r.path, now, now)
}

// load evaluates the RC in a bash sub-process and returns the resulting
// environment.  Even on error a usable environment is returned (the previous
// environment with this RC's metadata stamped on it), mirroring the
// reference, whose export path prints that environment before failing.
func (r *rc) load(prevEnv Env) (Env, error) {
	newEnv := prevEnv.copy()
	newEnv["DIRENV_WATCHES"] = r.times.marshal()

	finish := func(env Env, err error) (Env, error) {
		env["DIRENV_DIR"] = "-" + filepath.Dir(absPath(r.path))
		env["DIRENV_FILE"] = absPath(r.path)
		diff := buildEnvDiff(prevEnv, env)
		env["DIRENV_DIFF"] = diff.serialize()
		if err == nil && !r.cfg.HideEnvDiff {
			if s := diff.summary(); s != "" {
				logStatus("export %s", s)
			}
		}
		return env, err
	}

	switch r.allowed() {
	case deniedStatus:
		return finish(newEnv, nil)
	case blockedStatus:
		return finish(newEnv, fmt.Errorf("%s is blocked. Run `direnv allow` to approve its content", absPath(r.path)))
	}

	fn := "source_env"
	if filepath.Base(r.path) == ".env" {
		fn = "dotenv"
	}
	script := fmt.Sprintf("eval \"$(\"%s\" stdlib)\" && __main__ %s %s", r.cfg.SelfPath, fn, bashEscape(absPath(r.path)))
	if r.cfg.StrictEnv {
		script = "set -euo pipefail && " + script
	}
	cmd := exec.Command(r.cfg.BashPath, "-c", script)
	cmd.Env = newEnv.toSlice()
	cmd.Stderr = os.Stderr
	if r.cfg.DisableStdin {
		if devnull, err := os.OpenFile(os.DevNull, os.O_RDONLY, 0); err == nil {
			defer devnull.Close()
			cmd.Stdin = devnull
		}
	} else {
		cmd.Stdin = os.Stdin
	}
	out, err := cmd.Output()
	if err != nil {
		return finish(newEnv, err)
	}
	if len(out) > 0 {
		var dumped Env
		if jerr := jsonUnmarshal(out, &dumped); jerr != nil {
			return finish(newEnv, jerr)
		}
		newEnv = dumped
	}
	return finish(newEnv, nil)
}
