func (murexShell) hook() (string, error) {
	return "event: onPrompt direnv_hook=before {\n\t\"/SELF\" export murex -> set exports\n\tif { $exports != \"\" } {\n\t\t$exports -> :json: formap key value {\n\t\t\tif { is-null value } then {\n\t\t\t\t!export \"$key\"\n\t\t\t} else {\n\t\t\t\t$value -> export \"$key\"\n\t\t\t}\n\t\t}\n\t}\n}\n", nil
}
