}
func (systemdShell) unsetKV(k string) string { return "" }

// --- whole-map serialisation -------------------------------------------------

// ptrMap converts an Env/diff to map[string]*string for JSON-like shells.
func ptrMapFromEnv(e Env) map[string]*string {
	m := make(map[string]*string, len(e))
	for k, v := range e {
		vv := v
		m[k] = &vv
	}
	return m
}
func ptrMapFromDiff(d *envDiff) map[string]*string {
	m := make(map[string]*string)
	for k := range d.Prev {
		m[k] = nil
	}
	for k, v := range d.Next {
		vv := v
		m[k] = &vv
	}
	return m
}

func isJSONShell(name string) bool {
	switch name {
	case "json", "elvish", "murex", "gzenv":
		return true
	}
	return false
}

// shellDump renders a full environment for the given shell (the `dump` and
// `dotenv` commands).
func shellDump(name string, e Env) string {
	sh := shells[name]
	switch name {
	case "json":
		data, _ := jsonMarshalIndent(e)
		return string(data)
	case "elvish", "murex":
		data, _ := json.Marshal(e)
		return string(data) + "\n"
	case "gzenv":
		return gzMarshal(e)
	default:
		var b strings.Builder
		for k, v := range e {
			b.WriteString(sh.exportKV(k, v))
		}
		return b.String()
	}
}

// shellExportDiff renders a diff for the given shell (the `export` command).
func shellExportDiff(name string, d *envDiff) string {
	sh := shells[name]
	switch name {
	case "json":
		data, _ := jsonMarshalIndent(ptrMapFromDiff(d))
		return string(data)
	case "elvish", "murex":
		data, _ := json.Marshal(ptrMapFromDiff(d))
		return string(data) + "\n"
	case "gzenv":
		return gzMarshal(ptrMapFromDiff(d))
	default:
		changes := ptrMapFromDiff(d)
		if len(changes) == 0 {
			// Preserve the reference behaviour for shells such as json in
			// the no-change case handled by callers: they still print a
			// representation when an update happened with an empty diff.
		}
		var b strings.Builder
		for k, v := range changes {
			if v == nil {
				b.WriteString(sh.unsetKV(k))
			} else {
				b.WriteString(sh.exportKV(k, *v))
			}
		}
		return b.String()
	}
}
EOF
gofmt -w shells.go"}

