{"command":"cat > semver.go <<'EOF'
package main

import (
	"strings"
)

// A small semantic-version implementation matching golang.org/x/mod/semver's
// Canonical/Compare semantics, which is what the version check relies on:
// missing minor/patch components are filled with zero, numeric components
// may not have leading zeroes and build metadata is ignored for comparison.

type semver struct {
	major, minor, patch string
	pre                 []string
}

func isNumeric(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

func validNumericPart(s string) bool {
	if !isNumeric(s) {
		return false
	}
	if len(s) > 1 && s[0] == '0' {
		return false
	}
	return true
}

func parseSemver(v string) (semver, bool) {
	var sv semver
	if !strings.HasPrefix(v, "v") {
		return sv, false
	}
	s := v[1:]
	// Build metadata.
	if i := strings.IndexByte(s, '+'); i >= 0 {
		build := s[i+1:]
		if build == "" {
			return sv, false
		}
		for _, id := range strings.Split(build, ".") {
			if id == "" || !validIdentChars(id) {
				return sv, false
			}
		}
		s = s[:i]
	}
	// Prerelease.
	if i := strings.IndexByte(s, '-'); i >= 0 {
		pre := s[i+1:]
		if pre == "" {
			return sv, false
		}
		parts := strings.Split(pre, ".")
		for _, id := range parts {
			if id == "" || !validIdentChars(id) {
				return sv, false
			}
			if isNumeric(id) && len(id) > 1 && id[0] == '0' {
				return sv, false
			}
		}
		sv.pre = parts
		s = s[:i]
