package main

import (
	"encoding/json"
	"fmt"
	"path/filepath"
	"time"
)

type statusRC struct {
	Allowed int    `json:"allowed"`
	Path    string `json:"path"`
}

func rcStatusJSON(r *rc) *statusRC {
	if r == nil {
		return nil
	}
	return &statusRC{Allowed: int(r.allowed()), Path: r.path}
}

func relTo(base, path string) string {
	rel, err := filepath.Rel(base, path)
	if err != nil {
		return path
	}
	return rel
}

func printRCState(prefix string, r *rc) {
	if r == nil {
		if prefix == "Loaded" {
			fmt.Println("No .envrc or .env loaded")
		} else {
			fmt.Println("No .envrc or .env found")
		}
		return
	}
	fmt.Printf("%s RC path %s\n", prefix, r.path)
	dir := filepath.Dir(r.path)
	for _, ft := range r.times.list {
		t := time.Unix(ft.Modtime, 0).UTC().Format(time.RFC3339)
		fmt.Printf("%s watch: %q - %s\n", prefix, relTo(dir, ft.Path), t)
	}
	fmt.Printf("%s RC allowed %d\n", prefix, int(r.allowed()))
	fmt.Printf("%s RC allowPath %s\n", prefix, r.allowPath)
}

func cmdStatus(args []string) error {
	cfg, err := loadConfig()
	if err != nil {
		return err
	}
	jsonOut := false
	for _, a := range args {
		if a == "--json" || a == "-json" {
			jsonOut = true
		}
	}
	foundRC := cfg.findRC()
	loadedRC := cfg.loadedRC()
	if jsonOut {
		out := map[string]interface{}{
			"config": map[string]interface{}{
				"ConfigDir": cfg.ConfigDir,
				"SelfPath":  cfg.SelfPath,
			},
			"state": map[string]interface{}{
				"foundRC":  rcStatusJSON(foundRC),
				"loadedRC": rcStatusJSON(loadedRC),
			},
		}
		// Marshal through ordered structs to get the reference layout.
		type cfgJSON struct {
			ConfigDir string
			SelfPath  string
		}
		type stateJSON struct {
			FoundRC  *statusRC `json:"foundRC"`
			LoadedRC *statusRC `json:"loadedRC"`
		}
		type rootJSON struct {
			Config cfgJSON   `json:"config"`
			State  stateJSON `json:"state"`
		}
		_ = out
		data, _ := jsonMarshalIndent(rootJSON{
			Config: cfgJSON{ConfigDir: cfg.ConfigDir, SelfPath: cfg.SelfPath},
			State:  stateJSON{FoundRC: rcStatusJSON(foundRC), LoadedRC: rcStatusJSON(loadedRC)},
		})
		fmt.Println(string(data))
		return nil
	}
	fmt.Printf("direnv exec path %s\n", cfg.SelfPath)
	fmt.Printf("DIRENV_CONFIG %s\n", cfg.ConfigDir)
	fmt.Printf("bash_path %s\n", cfg.BashPath)
	fmt.Printf("disable_stdin %v\n", cfg.DisableStdin)
	fmt.Printf("warn_timeout %s\n", cfg.WarnTimeout.String())
	fmt.Printf("whitelist.prefix %v\n", cfg.whitelistPrefix)
	fmt.Printf("whitelist.exact %v\n", cfg.whitelistExact)
	printRCState("Loaded", loadedRC)
	printRCState("Found", foundRC)
	return nil
}

var _ = json.Marshal
EOF
