package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// requiredFilePath returns the on-disk approval file for a required file:
//   <data>/allowed-required/<sha256(envrcAbs+"\n")>/<sha256(reqAbs+"\n"+content)>
func requiredApprovalPath(cfg *config, envrcPath, reqAbs string, content []byte) string {
	parent := hashForPath(absPath(envrcPath), nil)
	return filepath.Join(cfg.requiredDir(), parent, hashForPath(reqAbs, content))
}

func requiredIsApproved(cfg *config, envrcPath, rel string) bool {
	dir := filepath.Dir(absPath(envrcPath))
	reqAbs := filepath.Join(dir, rel)
	content, err := os.ReadFile(reqAbs)
	if err != nil {
		return false
	}
	_, err = os.Stat(requiredApprovalPath(cfg, envrcPath, reqAbs, content))
	return err == nil
}

// approveRequired records approval for one relative required file.  The
// stored file's content is the path exactly as supplied plus a newline.
func approveRequired(cfg *config, envrcPath, rel string) error {
	dir := filepath.Dir(absPath(envrcPath))
	reqAbs := filepath.Join(dir, rel)
	content, err := os.ReadFile(reqAbs)
	if err != nil {
		if os.IsNotExist(err) {
			return fmt.Errorf("required file does not exist: %s", rel)
		}
		return err
	}
	approval := requiredApprovalPath(cfg, envrcPath, reqAbs, content)
	if err := os.MkdirAll(filepath.Dir(approval), 0o755); err != nil {
		return err
	}
	return os.WriteFile(approval, []byte(rel+"\n"), 0o644)
}

func cmdCheckRequired(args []string) error {
	cfg, err := loadConfig()
	if err != nil {
		return err
	}
	if len(args) < 1 {
		return fmt.Errorf("a shell name is required")
	}
	shellName := args[0]
	if _, err := getShell(shellName); err != nil {
		return err
	}
	if len(args) < 2 {
		return fmt.Errorf("an envrc path is required")
	}
	envrcPath := args[1]
	if len(args) < 3 {
		return fmt.Errorf("at least one file path is required")
	}
	paths := args[2:]
	// Validation of each path happens (in order) before any approval
	// output is produced for the invalid ones.
	for _, p := range paths {
		if filepath.IsAbs(p) {
			fmt.Printf("log_error %s;\nexit 1;\n", bashEscape(fmt.Sprintf("require_allowed: path must be relative: %s", p)))
			return nil
		}
		if strings.Contains(p, "..") {
			fmt.Printf("log_error %s;\nexit 1;\n", bashEscape(fmt.Sprintf("require_allowed: path must not contain '..': %s", p)))
			return nil
		}
	}
	var unapproved []string
	for _, p := range paths {
		if !requiredIsApproved(cfg, envrcPath, p) {
			unapproved = append(unapproved, p)
		}
	}
	if len(unapproved) == 0 {
		return nil
	}
	joined := strings.Join(unapproved, ":")
	// Export DIRENV_REQUIRED via the target shell.  This goes through the
	// same whole-env serialisation the export command uses for a one-key
	// env; for JSON-like shells that means a JSON object is printed
	// immediately followed by the bash log_error line.
	one := Env{"DIRENV_REQUIRED": joined}
	// For text shells exportKV is used directly to match the reference
	// (which does not add a trailing newline here for bash).
	if isJSONShell(shellName) {
		fmt.Print(shellDump(shellName, one))
		// shellDump for json has no trailing newline; for elvish/murex it
		// does (handled inside shellDump).  The reference's check-required
		// output for json is the object followed directly by log_error.
		if shellName == "elvish" || shellName == "murex" {
			// shellDump adds "\n"; the reference output also separates the
			// log line, so keep it.
		}
	} else {
		sh := shells[shellName]
		fmt.Print(sh.exportKV("DIRENV_REQUIRED", joined))
	}
	var msg string
	if len(unapproved) == 1 {
		msg = fmt.Sprintf("%s requires approval. Run 'direnv allow' to approve.", unapproved[0])
	} else {
		// "a and b require ..." / "a, b and c require ..."
		var list string
		if len(unapproved) == 2 {
			list = unapproved[0] + " and " + unapproved[1]
		} else {
			list = strings.Join(unapproved[:len(unapproved)-1], ", ") + " and " + unapproved[len(unapproved)-1]
		}
		msg = fmt.Sprintf("%s require approval. Run 'direnv allow' to approve.", list)
	}
	fmt.Printf("log_error %s;\nexit 0;\n", bashEscape(msg))
	return nil
}
EOF
gofmt -w required.go"}

