{"command":"cat > cmd_allow.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

func cmdAllow(args []string) error {
	cfg, err := loadConfig()
	if err != nil {
		return err
	}
	r, err := cfg.findRCForAllow(firstArg(args), len(args) > 0)
	if err != nil {
		return err
	}
	if err := r.allow(); err != nil {
		return err
	}
	// Required files recorded in the (shell) environment by a previous
	// blocked load are approved as part of the same `direnv allow`.
	if req, ok := cfg.env["DIRENV_REQUIRED"]; ok && req != "" {
		for _, rel := range strings.Split(req, ":") {
			fmt.Printf("direnv: allowing %s\n", rel)
			if err := approveRequired(cfg, r.path, rel); err != nil {
				return err
			}
		}
	} else if ok && req == "" {
		// The reference splits on ":" unconditionally when the variable
		// is present; an empty value therefore yields one empty entry.
		// That path is only reachable with a hand-crafted environment.
		// Match the simple observed behaviour for check-required's own
		// empty entry: it attempts to allow "".
		fmt.Printf("direnv: allowing %s\n", "")
		if err := approveRequired(cfg, r.path, ""); err != nil {
			return err
		}
	}
	return nil
}

func cmdBlock(args []string) error {
	cfg, err := loadConfig()
	if err != nil {
