{"command":"cat > dotenv.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"strings"
)

func isDotenvSpace(c byte) bool { return c == ' ' || c == '\t' || c == '\f' }

func skipDotenvSpaces(s string, i int) int {
	for i < len(s) && isDotenvSpace(s[i]) {
		i++
	}
	return i
}

func isKeyChar(c byte) bool {
	return c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_' || c == '.'
}

// valueStart locates the start of the value for a line that is shaped like an
// assignment, or -1.  It is only used for multiline-quote detection.
func dotenvValueStart(line string) int {
	i := skipDotenvSpaces(line, 0)
	if strings.HasPrefix(line[i:], "export") {
		j := i + len("export")
		if j < len(line) && isDotenvSpace(line[j]) {
			i = skipDotenvSpaces(line, j)
		}
	}
	startKey := i
	for i < len(line) && isKeyChar(line[i]) {
		i++
	}
	if i == startKey {
		return -1
	}
	i = skipDotenvSpaces(line, i)
	if i < len(line) && line[i] == '=' {
		return skipDotenvSpaces(line, i+1)
	}
	if i < len(line) && line[i] == ':' {
		j := i + 1
		if j < len(line) && isDotenvSpace(line[j]) {
			return skipDotenvSpaces(line, j)
		}
	}
	return -1
}

func expandDotenv(value string, local, base Env) string {
	return os.Expand(value, func(name string) string {
		key := name
		def := ""
		hasDef := false
		if idx := strings.Index(name, ":-"); idx >= 0 {
			key = name[:idx]
			def = name[idx+2:]
			hasDef = true
		}
		if v, ok := local[key]; ok {
			return v
		}
		if v, ok := base[key]; ok && v != "" {
			return v
		}
		if hasDef {
			return def
		}
		return base[key]
	})
}

func processDoubleQuoted(raw string, local, base Env) string {
	// Step 1: \n and \r sequences become the real characters.
	s := strings.NewReplacer("\\n", "\n", "\\r", "\r").Replace(raw)
	// Step 2: a backslash escapes the following character (dropping the
