	"strconv"
)

func cmdDump(args []string) error {
	shellName := "gzenv"
	if len(args) > 0 {
		shellName = args[0]
	}
	if _, err := getShell(shellName); err != nil {
		return err
	}
	env := newEnv()
	out := shellDump(shellName, env)
	dumpFile := ""
	if len(args) > 1 {
		dumpFile = args[1]
	} else {
		dumpFile = env["DIRENV_DUMP_FILE_PATH"]
	}
