		fmt.Println(out)
		return nil
	}
	f, err := os.OpenFile(dumpFile, os.O_WRONLY, 0)
	if err != nil {
		return err
	}
	defer f.Close()
	_, err = fmt.Fprintln(f, out)
	return err
