import (
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"syscall"
	"unsafe"
)

// --- SRI parsing -------------------------------------------------------------

type sriHash struct {
	algo   string
	digest []byte
	raw    string
}

func parseSRI(s string) (*sriHash, error) {
	i := strings.IndexByte(s, '-')
	if i < 0 {
		return nil, fmt.Errorf("sri: not a hash %s", s)
	}
	algo := s[:i]
	switch algo {
	case "sha256", "sha384", "sha512":
	default:
		return nil, fmt.Errorf("sri: unsupported algo %s", algo)
	}
	digest, err := base64.StdEncoding.DecodeString(s[i+1:])
	if err != nil {
		return nil, err
	}
	return &sriHash{algo: algo, digest: digest, raw: s}, nil
}

func (h *sriHash) String() string {
	return h.algo + "-" + base64.StdEncoding.EncodeToString(h.digest)
}
func (h *sriHash) hexDigest() string { return hex.EncodeToString(h.digest) }

func sha256SRI(dataHash []byte) *sriHash {
	return &sriHash{algo: "sha256", digest: dataHash}
}

func isTTY(f *os.File) bool {
	// TCGETS ioctl: succeeds only on a terminal.
	var termios [64]byte
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), uintptr(0x5401), uintptr(unsafe.Pointer(&termios[0])))
	return errno == 0
}

// fetchURL downloads url into the CAS and returns (path, actualHash, err).
func fetchURL(cfg *config, url string, expected *sriHash) (string, *sriHash, error) {
	casDir := cfg.casDir()
	if expected != nil {
		finalPath := filepath.Join(casDir, expected.hexDigest())
		if _, err := os.Stat(finalPath); err == nil {
			return finalPath, expected, nil
		}
	}
	if err := os.MkdirAll(casDir, 0o755); err != nil {
		return "", nil, err
	}
	resp, err := http.Get(url) //nolint:bodyclose
	if err != nil {
		return "", nil, err
	}
	defer resp.Body.Close()
	if resp.StatusCode != 200 {
		return "", nil, fmt.Errorf("expected status code 200 but got %d", resp.StatusCode)
	}
	tmpfile, err := os.CreateTemp(casDir, "tmp*")
	if err != nil {
		return "", nil, err
	}
	// This deferred cleanup reproduces the reference's warnings when the
	// temp file has already been closed and renamed into place.
	defer func() {
		if err := tmpfile.Close(); err != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to close temp file: %v\n", err)
		}
		if err := os.Remove(tmpfile.Name()); err != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to remove temp file %s: %v\n", tmpfile.Name(), err)
		}
	}()
	h := sha256.New()
	if _, err := io.Copy(io.MultiWriter(tmpfile, h), resp.Body); err != nil {
		return "", nil, err
	}
	actual := sha256SRI(h.Sum(nil))
	finalPath := filepath.Join(casDir, actual.hexDigest())
	if _, err := os.Stat(finalPath); err != nil {
		if cerr := tmpfile.Close(); cerr != nil {
			_ = cerr
		}
		if rerr := os.Rename(tmpfile.Name(), finalPath); rerr != nil {
			return "", nil, rerr
		}
		if cerr := os.Chmod(finalPath, 0o500); cerr != nil {
			return "", nil, cerr
		}
	}
	return finalPath, actual, nil
}

func cmdFetchURL(args []string) error {
	cfg, err := loadConfig()
	if err != nil {
		return err
	}
	if len(args) == 0 {
		return fmt.Errorf("missing URL argument")
	}
	url := args[0]
	var expected *sriHash
	if len(args) > 1 {
		h, err := parseSRI(args[1])
		if err != nil {
			return err
		}
		expected = h
	}
	path, actual, err := fetchURL(cfg, url, expected)
	if err != nil {
		return err
	}
	if expected == nil {
		if isTTY(os.Stdout) {
			fmt.Printf("Found hash: %s\n", actual.String())
			fmt.Println()
			fmt.Println("Invoke fetchurl again with the hash as an argument to get the disk location:")
			fmt.Println()
			fmt.Printf("  direnv fetchurl %q %q\n", url, actual.String())
			fmt.Printf("  #=> %s\n", path)
		} else {
			fmt.Println(actual.String())
		}
		return nil
	}
	if expected.String() != actual.String() {
		return fmt.Errorf("hash mismatch. Expected '%s' but got '%s'", expected.String(), actual.String())
	}
	fmt.Println(path)
	return nil
}
EOF
