{"command":"cat > cmd_edit.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
)

var defaultEditors = []string{"editor", "subl", "mate", "open", "nano", "vim", "emacs"}

func findEditor(env Env) (string, error) {
	if ed := env["EDITOR"]; ed != "" {
		return ed, nil
	}
	logError("$EDITOR not found.")
	for _, name := range defaultEditors {
		if p, err := exec.LookPath(name); err == nil {
			_ = p
			return name, nil
		}
	}
	return "", fmt.Errorf("could not find a default editor in the PATH")
}

func cmdEdit(args []string) error {
	cfg, err := loadConfig()
	if err != nil {
		return err
	}
	// RC found from the current working directory.  This (and its file
	// times) is what determines whether an allow happens afterwards, even
	// when the file actually edited is a different path given as argument.
	foundRC := cfg.findRC()

	var rcPath string
	if len(args) > 0 {
		arg := args[0]
		if fi, err := os.Stat(arg); err == nil && fi.IsDir() {
			rcPath = filepath.Join(arg, ".envrc")
		} else {
			rcPath = arg
		}
	} else {
		if foundRC == nil {
			return fmt.Errorf(".envrc or .env not found. Use `direnv edit .` to create a new .envrc in the current directory")
		}
		rcPath = foundRC.path
	}

	// Times to compare after editing: the found RC's watches if there is
	// one, otherwise the (possibly not yet existing) edited file itself.
	var times *fileTimes
	if foundRC != nil {
		times = &fileTimes{list: append([]fileTime{}, foundRC.times.list...)}
	} else {
		times = newFileTimes()
		_ = times.add(rcPath)
	}

	editor, err := findEditor(cfg.env)
	if err != nil {
		return err
	}
	cmd := exec.Command(cfg.BashPath, "-c", editor+" "+bashEscape(rcPath))
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Env = cfg.env.toSlice()
	if err := cmd.Run(); err != nil {
		return err
	}

	// Re-find the RC from the working directory and allow it if the
	// previously found RC's watched files have changed.
	foundAfter := cfg.findRC()
	debugLogf("cmd_edit", "cmd_edit.go:73", "foundRC: %v", foundAfter)
	debugLogf("cmd_edit", "cmd_edit.go:74", "times: %v", times)
	checkErr := times.checkAll()
	debugLogf("cmd_edit", "cmd_edit.go:76", "times.Check(): %v", checkErr)
	if checkErr != nil && foundAfter != nil {
		// Also require the edited file to be that RC when there was no
		// previously found RC (creation via `direnv edit .`).
		return foundAfter.allowForEdit(foundRC, rcPath)
	}
	return nil
}

// allowForEdit allows the re-found RC.  When there was no RC before editing
// the file that was created must be the re-found RC itself.
func (r *rc) allowForEdit(before *rc, editedPath string) error {
	if before == nil {
		if absPath(r.path) != absPath(editedPath) {
			return nil
		}
	}
	return r.allow()
}
EOF
gofmt -w cmd_edit.go"}

